export const getGetCrmExpiringPointsUrl = (id: string,
    params?: GetCrmExpiringPointsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/crm/clients/${id}/expiring-points?${stringifiedParams}` : `/api/crm/clients/${id}/expiring-points`
}

